```python
"""Card-style wallet: holds, partial captures, refunds and fees.

Amounts are integer minor units. available = ledger - held.

Incident fixes:
- Final capture: the uncaptured remainder is released from held.
- Captures: records are keyed only by capture_id. Keying by hold_id made a
  second partial capture replay the first one.
- Capture replay: checked before anything else, so it works in any hold state.
- Expiry: sweep_expired no longer expires a hold at exactly expires_at.
- Sweep: only the uncaptured remainder is released, not the full hold amount.
- Fees: calculated with exact integer ROUND_HALF_EVEN, not float half-up.
- Refunds: the limit applies to the running total across all partial refunds.
- Refund fees: fee_back is derived from the cumulative total, using the new
  "fee_refunded" key on the capture record, so rounding cannot drift.
- Amounts: non-integer amounts are rejected, as are negative amounts anywhere
  and zero amounts for holds, captures and refunds. Negative values could
  otherwise bypass the hold and refund limits.
"""


class WalletError(Exception):
    pass


MIN_FEE = 30
FEE_BPS = 250
BPS_DENOMINATOR = 10000


def _div_half_even(numerator, denominator):
    """Divide non-negative integers, rounding ROUND_HALF_EVEN, without floats."""
    quotient, remainder = divmod(numerator, denominator)
    twice_remainder = remainder * 2
    if twice_remainder > denominator or (
        twice_remainder == denominator and quotient % 2 == 1
    ):
        quotient += 1
    return quotient


def _check_amount(amount, minimum=1):
    if isinstance(amount, bool) or not isinstance(amount, int):
        raise WalletError("amount must be an integer in minor units")
    if amount < minimum:
        raise WalletError("amount out of range")


def fee_for(amount):
    return max(MIN_FEE, _div_half_even(amount * FEE_BPS, BPS_DENOMINATOR))


class Wallet:
    def __init__(self):
        self.ledger = {}
        self.held = {}
        self.holds = {}
        self.captures = {}
        self.refunds = {}
        self.merchant = 0
        self.revenue = 0

    def deposit(self, account, amount):
        _check_amount(amount, minimum=0)
        self.ledger[account] = self.ledger.get(account, 0) + amount

    def available(self, account):
        return self.ledger.get(account, 0) - self.held.get(account, 0)

    def place_hold(self, hold_id, account, amount, expires_at):
        if hold_id in self.holds:
            return self.holds[hold_id]
        _check_amount(amount)
        if self.available(account) < amount:
            raise WalletError("insufficient funds")
        hold = {"account": account, "amount": amount, "captured": 0, "status": "OPEN", "expires_at": expires_at}
        self.holds[hold_id] = hold
        self.held[account] = self.held.get(account, 0) + amount
        return hold

    def _release_rest(self, hold):
        self.held[hold["account"]] -= hold["amount"] - hold["captured"]

    def capture(self, capture_id, hold_id, amount, now, final=False):
        if capture_id in self.captures:
            return self.captures[capture_id]
        hold = self.holds[hold_id]
        _check_amount(amount)
        if hold["status"] != "OPEN":
            raise WalletError("hold not open")
        if now > hold["expires_at"]:
            raise WalletError("hold expired")
        if hold["captured"] + amount > hold["amount"]:
            raise WalletError("over capture")
        fee = fee_for(amount)
        hold["captured"] += amount
        self.held[hold["account"]] -= amount
        self.ledger[hold["account"]] -= amount
        self.merchant += amount - fee
        self.revenue += fee
        record = {
            "capture_id": capture_id,
            "hold_id": hold_id,
            "amount": amount,
            "fee": fee,
            "refunded": 0,
            "fee_refunded": 0,
        }
        self.captures[capture_id] = record
        if final:
            self._release_rest(hold)
            hold["status"] = "CLOSED"
        return record

    def void(self, hold_id):
        hold = self.holds[hold_id]
        if hold["status"] != "OPEN":
            return hold
        self._release_rest(hold)
        hold["status"] = "VOIDED"
        return hold

    def sweep_expired(self, now):
        expired = []
        for hold_id, hold in self.holds.items():
            if hold["status"] == "OPEN" and now > hold["expires_at"]:
                self._release_rest(hold)
                hold["status"] = "EXPIRED"
                expired.append(hold_id)
        return expired

    def refund(self, refund_id, capture_id, amount):
        if refund_id in self.refunds:
            return self.refunds[refund_id]
        capture = self.captures[capture_id]
        _check_amount(amount)
        total_refunded = capture["refunded"] + amount
        if total_refunded > capture["amount"]:
            raise WalletError("over refund")
        # Each refund pays the gap between the cumulative fee owed and the fee
        # already returned, so the running total always matches the formula.
        total_fee_back = _div_half_even(capture["fee"] * total_refunded, capture["amount"])
        fee_back = total_fee_back - capture["fee_refunded"]
        capture["refunded"] = total_refunded
        capture["fee_refunded"] = total_fee_back
        account = self.holds[capture["hold_id"]]["account"]
        self.ledger[account] += amount
        self.merchant -= amount - fee_back
        self.revenue -= fee_back
        record = {"refund_id": refund_id, "capture_id": capture_id, "amount": amount, "fee_back": fee_back}
        self.refunds[refund_id] = record
        return record
